    @staticmethod
    def new(name):
        os.makedirs(name)
        os.chdir(name)

        with open("pizza.json", "w", encoding="utf-8") as file:
            content = {
                "name"   : name,
                "version": "1.0",
                "desc"   : _("项目描述", "Project description"),
                "author" : _("作者名称", "Author name"),
                "main"   : "src/main.py:main",
                "deps"    : [],
                "scripts": {},
                "build": {
                    "icon"   : None,
                    "console": True,
                    "skip"   : False
                }
            }
            json.dump(content, file, indent=4, ensure_ascii=False)

        os.makedirs("src")
        os.chdir("src")

        with open("main.py", "w", encoding="utf-8") as file:
            content = "def main():\n    print(\"Hello,World!\")"
            file.write(content)

        print(_("╭─ Pizza ────────" + "─" * cnlen(name) + "╮", "╭─ Pizza ───────────────────────" + "─" * cnlen(name) + "╮"))
